"""Public matched-line spectral sensitivity analysis for Landini's long peak."""
import cmath
import json
import math
import random
import re
from collections import Counter, defaultdict
from statistics import fmean, median

from vs import corpus

EDITIONS = ('zl', 'it')
BLOCK = 1024
N_PERM = {'train': 19, 'evaluation': 99}
RAW = re.compile('[a-z]+')
FOLIO = re.compile(r'f\d+')
GLYPH_ID = {char: index for index, char in enumerate('abcdefghijklmnopqrstuvwxyz#')}
BANDS = {'center': (0.90, 1.10), 'short': (0.65, 0.80), 'long': (1.25, 1.50)}


def aligned_corpus():
    parts = defaultdict(dict)
    for ed in EDITIONS:
        for part,pages in zip(N_PERM, corpus.split_pages('practice',ed)):
            lines = {line.id: ''.join(line.words)
                     for page in pages for line in page.lines if line.unit == 'P'
                     and line.words and all(RAW.fullmatch(word) for word in line.words)}
            parts[part][ed] = lines
    result = {}
    for part in N_PERM:
        ids = [locus for locus in parts[part]['zl'] if locus in parts[part]['it']]
        result[part] = {ed: [(FOLIO.match(locus)[0], parts[part][ed][locus]) for locus in ids]
                        for ed in EDITIONS}
    return result


def choose_center(paired_training):
    lengths = Counter(len(line) for rows in paired_training.values() for _,line in rows)

    def neighborhood(center):
        return sum((3-abs(delta))*lengths[center+delta] for delta in range(-2,3))

    return min(lengths, key=lambda x:(-neighborhood(x),x))


def bins_for(period,block):
    return {band:tuple(k for k in range(2,block//2)
                      if lo*period <= block/k <= hi*period)
            for band,(lo,hi) in BANDS.items()}


class Spectrum:
    def __init__(self, center, block):
        self.block = block
        self.band_bins = bins_for(center,block)
        assert all(self.band_bins.values())
        self.weights = [0.5 - 0.5*math.cos(2*math.pi*i/block) for i in range(block)]
        self.window_energy = sum(x*x for x in self.weights)
        bins = sorted(set().union(*self.band_bins.values()))
        self.basis = {k:tuple(cmath.exp(-2j*math.pi*k*i/block)*w for i,w in enumerate(self.weights))
                      for k in bins}

    def band_power(self, text):
        n = self.block
        glyphs = [GLYPH_ID[c] for c in text]
        blocks = [glyphs[i:i+n] for i in range(0,len(glyphs)-n+1,n)]
        assert blocks
        spec = {}
        for k,vectors in self.basis.items():
            power = 0.0
            for block in blocks:
                sums = [0j]*len(GLYPH_ID)
                for char,v in zip(block,vectors):
                    sums[char] += v
                power += sum(z.real*z.real+z.imag*z.imag for z in sums)
            spec[k] = power/(len(blocks)*self.window_energy)
        band = {name:fmean(spec[k] for k in bins) for name,bins in self.band_bins.items()}
        return {'band_power':band['center'],
                'peak_ratio':band['center']/fmean((band['short'],band['long'])),
                'shoulders':[band['short'],band['long']],
                'blocks':len(blocks), 'used_glyphs':len(blocks)*n,
                'band_bins_power':spec}


def flat(rows):
    return ''.join(line for _,line in rows)


def shuffle_global(rows,rng):
    sequence = list(flat(rows))
    rng.shuffle(sequence)
    return ''.join(sequence)


def shuffle_folio_interiors(rows,rng):
    pools = defaultdict(list)
    for folio,line in rows:
        pools[folio].extend(line[1:-1])
    for pool in pools.values():
        rng.shuffle(pool)
    pointers = Counter()
    shuff = []
    for folio,line in rows:
        m = max(0,len(line)-2)
        start = pointers[folio]
        interior = ''.join(pools[folio][start:start+m])
        shuff.append(line[0]+interior+line[-1] if len(line)>1 else line)
        pointers[folio] += m
    return ''.join(shuff)


def shuffle_line_interiors(rows,rng):
    lines = []
    for _,line in rows:
        if len(line)<3:
            lines.append(line)
        else:
            middle = list(line[1:-1])
            rng.shuffle(middle)
            lines.append(line[0]+''.join(middle)+line[-1])
    return ''.join(lines)


def period_control(rows,rng,block,bin_index):
    sequence = list(shuffle_global(rows,rng))
    ends = set()
    position = 0
    for _,line in rows:
        ends.update((position,position+len(line)-1))
        position += len(line)
    for offset in range(0,len(sequence)-block+1,block):
        for pulse in range(bin_index):
            index = offset + (pulse*block)//bin_index + 2
            if index not in ends:
                sequence[index] = '#'
    striped = []
    offset = 0
    for folio,line in rows:
        striped.append((folio,''.join(sequence[offset:offset+len(line)])))
        offset += len(line)
    return striped


def validate_nulls(rows):
    observed = flat(rows)
    for fun in (shuffle_global,shuffle_folio_interiors,shuffle_line_interiors):
        x = fun(rows,random.Random(512))
        assert Counter(x)==Counter(observed)
        if fun == shuffle_global:
            continue
        i = 0
        before,after = defaultdict(Counter),defaultdict(Counter)
        for folio,line in rows:
            generated = x[i:i+len(line)]
            assert (line[0],line[-1]) == (generated[0],generated[-1])
            i += len(line)
            before[folio].update(line)
            after[folio].update(generated)
            if fun==shuffle_line_interiors:
                assert Counter(line)==Counter(generated)
        assert i==len(observed)
        assert dict(before)==dict(after)


def evaluate(rows,spectrum,nperm,seed,modes):
    real = spectrum.band_power(flat(rows))
    result = {'observed':real,'nulls':{}}
    for no,(name,fun) in enumerate(modes):
        rng = random.Random(seed+1000*no)
        controls = [spectrum.band_power(fun(rows,rng)) for _ in range(nperm)]
        metrics = {}
        for key in ('band_power','peak_ratio'):
            values = sorted(c[key] for c in controls)
            metrics[key] = {
                'permutations':nperm, 'median':median(values),
                'p_upper':(1+sum(x>=real[key] for x in values))/(nperm+1),
                'null_range':[values[0],values[-1]],
                'observed_over_null_median':real[key]/median(values),
            }
        result['nulls'][name] = metrics
    return result


def run():
    data = aligned_corpus()
    center = choose_center(data['train'])
    s = Spectrum(center,BLOCK)
    modes = [('global_glyph',shuffle_global),('folio_interiors',shuffle_folio_interiors)]
    result = {}
    for part,n in N_PERM.items():
        cases = {}
        for ed,rows in data[part].items():
            validate_nulls(rows)
            selected_modes = modes + ([('line_interiors',shuffle_line_interiors)] if part=='evaluation' else [])
            cases[ed] = evaluate(rows,s,n,26687,selected_modes)
            cases[ed]['lines'] = len(rows)
            cases[ed]['total_glyphs'] = len(flat(rows))
        result[part] = cases
    held = data['evaluation']['zl']
    mid = min(s.band_bins['center'],key=lambda k:abs(BLOCK/k-center))
    pulse_text = period_control(held,random.Random(6484),BLOCK,mid)
    validation = evaluate(pulse_text,s,19,42911,modes)
    return {'selected_period':center,'block_size':BLOCK,'bands_period_multipliers':BANDS,
            'bins':s.band_bins,'simulated_pulse_period':BLOCK/mid,'simulated_pulse':validation,
            'partitions':result}


if __name__ == '__main__':
    print(json.dumps(run(),indent=2))

