"""Boundary-only and within-folio sensitivities for the public spectral analysis."""
import json
import random
from collections import defaultdict
from itertools import groupby
from statistics import median

from vs import corpus

from voynich_spectral_lines import (
    BLOCK, EDITIONS, FOLIO, RAW, Spectrum, aligned_corpus, choose_center, evaluate, flat,
    shuffle_folio_interiors, shuffle_global,
)


def position(index,length):
    if index < 2:
        return ('start',index)
    if length-index <= 2:
        return ('end',length-index)
    return ('middle',0)


def independent_geometry(training,layout,seed):
    choices = defaultdict(list)
    for _,line in training:
        for index,char in enumerate(line):
            choices[position(index,len(line))].append(char)
    rng = random.Random(seed)
    return [(folio,''.join(rng.choice(choices[position(i,len(line))]) for i in range(len(line))))
            for folio,line in layout]


def within_folio_slices(rows,block):
    start = 0
    slices = []
    for _, group in groupby(rows,key=lambda row:row[0]):
        length = sum(len(line) for _,line in group)
        kept = length//block*block
        if kept:
            slices.append(slice(start,start+kept))
        start += length
    return slices


def no_crossing(rows,center):
    block = 512
    spectrum = Spectrum(center,block)
    slices = within_folio_slices(rows,block)
    assert slices

    def score(text):
        selected = ''.join(text[segment] for segment in slices)
        return spectrum.band_power(selected)

    observed = score(flat(rows))
    nulls = {}
    for name,fun in (('global_glyph',shuffle_global),('folio_interiors',shuffle_folio_interiors)):
        rng = random.Random(377)
        null = [score(fun(rows,rng)) for _ in range(49)]
        nulls[name] = {k: {'p_upper':(1+sum(x[k]>=observed[k] for x in null))/(len(null)+1),
                           'median':median(x[k] for x in null)}
                       for k in ('band_power','peak_ratio')}
    return {'observed':observed,'compared_folio_runs':len(slices),'nulls':nulls}


def relaxed_evaluation():
    parsed = {}
    for ed in EDITIONS:
        _,pages = corpus.split_pages('practice',ed)
        parsed[ed] = {line.id: ''.join(word for word in line.words if RAW.fullmatch(word))
                      for page in pages for line in page.lines if line.unit == 'P'}
    ids = [locus for locus in parsed['zl'] if parsed['zl'][locus] and parsed['it'].get(locus)]
    return {ed: [(FOLIO.match(locus)[0],parsed[ed][locus]) for locus in ids] for ed in EDITIONS}


def run():
    data = aligned_corpus()
    center = choose_center(data['train'])
    spectrum = Spectrum(center,BLOCK)
    modes = [('global_glyph',shuffle_global),('folio_interiors',shuffle_folio_interiors)]
    result = {}
    relaxed = relaxed_evaluation()
    for ed in EDITIONS:
        train = data['train'][ed]
        evalp = data['evaluation'][ed]
        trials = [evaluate(independent_geometry(train,evalp,seed),spectrum,19,seed,modes)
                  for seed in (2987,2988,2989)]
        less_strict = evaluate(relaxed[ed],spectrum,49,2138,modes)
        less_strict['lines'] = len(relaxed[ed])
        result[ed] = {'wide_sensitivity':no_crossing(evalp,center),'geometry_only':trials,
                      'retaining_clean_words_in_uncertain_lines':less_strict}
    return result


if __name__ == '__main__':
    print(json.dumps(run(),indent=2))
